"""Algorithm A: the order of Out(G) for a finite group given by a table."""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Optional, Sequence, Tuple

Table = Tuple[Tuple[int, ...], ...]  # table[a][b] = a*b, carrier {0,...,n-1}, identity 0


def mul(t: Table, a: int, b: int) -> int:
    return t[a][b]


def element_order(t: Table, a: int) -> int:
    k, x = 1, a
    while x != 0:
        x = mul(t, x, a)
        k += 1
    return k


def centre(t: Table) -> List[int]:
    n = len(t)
    return [z for z in range(n)
            if all(mul(t, z, a) == mul(t, a, z) for a in range(n))]


def generating_set(t: Table) -> List[int]:
    """A small generating set, found greedily; keeps the search space tiny."""
    n = len(t)
    gens: List[int] = []
    generated = {0}
    for a in range(1, n):
        if a in generated:
            continue
        gens.append(a)
        frontier = set(generated) | {a}
        while True:
            new = {mul(t, x, y) for x in frontier for y in frontier} | frontier
            if new == frontier:
                break
            frontier = new
        generated = frontier
        if len(generated) == n:
            break
    return gens


def extend(t: Table, gens: Sequence[int], images: Sequence[int]) -> Optional[List[int]]:
    """Close up gens |-> images multiplicatively; None if inconsistent or partial."""
    n = len(t)
    phi: Dict[int, int] = {0: 0}
    for gen, img in zip(gens, images):
        phi[gen] = img
    changed = True
    while changed:
        changed = False
        for a, fa in list(phi.items()):
            for b, fb in list(phi.items()):
                ab, fab = mul(t, a, b), mul(t, fa, fb)
                if ab in phi:
                    if phi[ab] != fab:
                        return None
                else:
                    phi[ab] = fab
                    changed = True
    return [phi[a] for a in range(n)] if len(phi) == n else None


def automorphism_count(t: Table) -> int:
    """|Aut(G)|, by enumerating order-preserving images of a generating set."""
    n = len(t)
    gens = generating_set(t)
    orders = [element_order(t, a) for a in range(n)]
    candidates = [[b for b in range(n) if orders[b] == orders[gen]] for gen in gens]
    count = 0
    for images in product(*candidates):
        phi = extend(t, gens, images)
        if phi is None or len(set(phi)) != n:
            continue
        if all(phi[mul(t, a, b)] == mul(t, phi[a], phi[b])
               for a in range(n) for b in range(n)):
            count += 1
    return count


def out_order(t: Table) -> int:
    """|Out(G)| = |Aut(G)| / (|G| / |Z(G)|): the number of symmetries of K(G,1)."""
    return automorphism_count(t) * len(centre(t)) // len(t)


if __name__ == "__main__":
    cyclic = lambda n: tuple(tuple((a + b) % n for b in range(n)) for a in range(n))
    for n in range(1, 13):
        print(f"K(Z/{n},1) has {out_order(cyclic(n))} self-equivalences (= phi({n}))")

